(() => {
  'use strict';const $=id=>document.getElementById(id),escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const stages=['Aguardando pagamento','Pedido confirmado','Em preparação','Coletado pela transportadora','Em transporte','Entregue'];
  const status=value=>({PAID:'Pago',WAITING_PAYMENT:'Pendente',PROCESSING:'Processando',AUTHORIZED:'Aguardando confirmação',REFUSED:'Recusado',REFUNDED:'Estornado',CANCELED:'Cancelado',CHARGEDBACK:'Contestado'}[value]||value);
  const money=value=>(Number(value||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),date=value=>new Date(value).toLocaleString('pt-BR');
  let challenge='',page=1,currentId='';
  async function api(path,body){const response=await fetch('/api/admin'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok){if(response.status===401&&!path.startsWith('/login/'))showLogin();throw Error(data.message||'Não foi possível concluir agora.');}return data;}
  function showLogin(){$('login-card').hidden=false;$('dashboard').hidden=true;$('logout').hidden=true;}
  async function load(){const data=await api('/orders?status='+encodeURIComponent($('filter').value)+'&page='+page);$('stats').innerHTML=[['Pedidos',data.stats.total||0],['Pagos',data.stats.paid||0],['Pendentes',data.stats.pending||0],['Total pago',money(data.stats.revenue)],['Reentregas pagas',money(data.stats.redeliveryRevenue)]].map(([label,value])=>`<div class="card"><span class="muted">${label}</span><strong>${escape(value)}</strong></div>`).join('');$('orders').innerHTML=data.orders.length?data.orders.map(order=>`<tr><td>${escape(order.order_code)}<small>${escape(date(order.created_at))}</small></td><td>${escape(order.customer.name)}<small>${escape(order.customer.email)}</small></td><td>${escape(money(order.amount))}</td><td><span class="badge ${order.payment_status==='PAID'?'paid':''}">${escape(status(order.payment_status))}</span></td><td>${escape(deliveryStatus(order))}</td><td><button data-order="${escape(order.id)}">Ver pedido</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhum pedido encontrado. Use “Sincronizar Umbrella” para buscar os pedidos existentes desta loja.</td></tr>';$('page').textContent='Página '+data.page;$('prev').disabled=page<=1;$('next').disabled=!data.hasMore;}
  async function enter(){$('login-card').hidden=true;$('dashboard').hidden=false;$('logout').hidden=false;await load();}
  function action(button,message,fn){return async event=>{if(event)event.preventDefault();button.disabled=true;message.textContent='';try{await fn();}catch(error){message.textContent=error.message;}finally{button.disabled=false;}};}
  $('login-form').addEventListener('submit',action($('login-form').querySelector('button'),$('login-message'),async()=>{const data=await api('/login/request',{email:$('email').value});challenge=data.challenge;$('code-form').hidden=false;$('login-form').hidden=true;$('login-message').textContent=data.message;$('otp').focus();}));
  $('code-form').addEventListener('submit',action($('code-form').querySelector('button'),$('login-message'),async()=>{await api('/login/verify',{challenge,code:$('otp').value});$('otp').value='';await enter();}));
  $('logout').onclick=action($('logout'),$('dashboard-message'),async()=>{await api('/logout',{});showLogin();$('code-form').hidden=true;$('login-form').hidden=false;});
  $('test-email').onclick=action($('test-email'),$('dashboard-message'),async()=>{const data=await api('/emails/test',{testId:crypto.randomUUID()});$('dashboard-message').textContent=data.emailStatus==='sent'?'Teste aceito pelo serviço de e-mail. Confira a caixa do administrador.':'Teste aguardando envio ou configuração. Confira as pendências.';});
  $('retry-emails').onclick=action($('retry-emails'),$('dashboard-message'),async()=>{const data=await api('/emails/retry',{});$('dashboard-message').textContent=data.results.length+' mensagem(ns) conferida(s). Mensagens recentes aguardam intervalo de segurança.';if(currentId&&$('order-dialog').open)await detail(currentId);});
  $('refresh').onclick=action($('refresh'),$('dashboard-message'),load);
  $('filter').onchange=async()=>{page=1;try{await load();}catch(error){$('dashboard-message').textContent=error.message;}};
  $('prev').onclick=async()=>{page=Math.max(1,page-1);try{await load();}catch(error){$('dashboard-message').textContent=error.message;}};
  $('next').onclick=async()=>{page++;try{await load();}catch(error){$('dashboard-message').textContent=error.message;}};
  $('sync').onclick=action($('sync'),$('dashboard-message'),async()=>{let n=1,total=0,more=true;while(more){$('dashboard-message').textContent='Sincronizando pedidos… página '+n;const data=await api('/sync',{page:n});total+=data.synced;more=data.hasMore;n++;}await load();$('dashboard-message').textContent=total+' pedido(s) sincronizado(s).';});
  $('close-dialog').onclick=()=>$('order-dialog').close();
  function attributionHtml(value){
    if(!value)return '<h3>Origem da compra</h3><p class="muted">Sem UTMs registradas (acesso direto ou pedido anterior à captura).</p>';
    return '<h3>Origem da compra</h3>'+['first','last'].map(touch=>{const data=value[touch];if(!data)return '';return '<h4>'+(touch==='first'?'Primeiro acesso':'Última campanha')+'</h4><dl>'+Object.entries(data).map(([key,value])=>'<dt><strong>'+escape(key)+'</strong></dt><dd style="overflow-wrap:anywhere">'+escape(value)+'</dd>').join('')+'</dl>';}).join('');
  }

  const deliveryStatus=order=>({failed:'3 tentativas sem sucesso',cancel_requested:'Cancelamento solicitado',redelivery_pending:'Pix de reentrega pendente'}[order.deliveryStatus]||stages[order.stage]);
  function deliveryControls(order){
    const d=order.delivery||{cycle:1,status:'active',attempts:[],fees:[]},paid=order.payment_status==='PAID',active=paid&&d.status==='active'&&order.stage<5;
    return '<section class="delivery-controls"><h3>Entrega · ciclo '+d.cycle+'</h3>'+
      (d.status==='cancel_requested'?'<p class="notice">Cliente solicitou cancelamento. Analise o pedido e entre em contato. Nenhum estorno foi realizado automaticamente.</p>':d.status==='failed'?'<p class="notice">Três tentativas sem sucesso. Aguardando a escolha do cliente. '+(d.feeAllowed?'Reentrega opcional de R$ 10,00 habilitada.':'Cobrança não habilitada; orientar o cliente pelo atendimento.')+'</p>':d.status==='redelivery_pending'?'<p class="notice">Taxa de reentrega aguardando confirmação. O novo prazo ainda não começou.</p>':'')+
      (active?'<p class="muted">Escolha uma etapa e confirme os dados no formulário abaixo.</p><div class="stage-actions" role="group" aria-label="Etapas da entrega">'+stages.slice(1).map((name,i)=>'<button type="button" class="secondary" data-stage="'+(i+1)+'" aria-pressed="'+(order.stage===i+1)+'">'+(i+1)+'. '+escape(name)+'</button>').join('')+'</div>':'')+
      '<h3>Tentativas de entrega</h3><ol class="attempt-list">'+d.attempts.map(a=>'<li><strong>'+a.number+'ª tentativa sem sucesso</strong> · '+escape(date(a.occurred_at))+'<p>'+escape(a.note)+' · '+escape(a.location)+'</p></li>').join('')+'</ol>'+
      (active&&order.stage===4?'<div class="attempt-actions">'+[1,2,3].map(n=>'<button type="button" data-attempt="'+n+'" '+(n!==d.attempts.length+1?'disabled':'')+'>'+n+'ª tentativa sem sucesso</button>').join('')+'</div><div id="attempt-editor"></div>':!paid?'<p class="muted">As tentativas ficam disponíveis após o pagamento e a etapa Em transporte.</p>':active?'<p class="muted">Para registrar tentativas, marque primeiro a etapa Em transporte.</p>':'')+
      (d.fees.length?'<h3>Taxas de reentrega</h3>'+d.fees.map(f=>'<p>Ciclo '+f.cycle+' → '+(f.cycle+1)+' · R$ 10,00 · '+escape({paid:'Pago',ready:'Pix pendente',creating:'Em geração',uncertain:'Em verificação — não gerar outra cobrança',closed:'Encerrado; contatar cliente',paid_review:'Pago; revisão manual necessária'}[f.state]||f.state)+'</p>').join(''):'')+'</section>';
  }
  function bindDeliveryControls(order){
    document.querySelectorAll('[data-stage]').forEach(button=>button.onclick=()=>{
      $('stage').value=button.dataset.stage;
      document.querySelectorAll('[data-stage]').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));
      $('note').value=stages[Number(button.dataset.stage)]+' — confirmado com a transportadora.';$('note').focus();
    });
    document.querySelectorAll('[data-attempt]').forEach(button=>button.onclick=()=>{
      const number=Number(button.dataset.attempt),actionId=crypto.randomUUID();
      $('attempt-editor').innerHTML='<form id="attempt-form" class="grid"><h4 class="full">Registrar '+number+'ª tentativa sem sucesso</h4><div><label for="attempt-date">Data e hora reais</label><input type="datetime-local" step="1" id="attempt-date" required></div><div><label for="attempt-reason">Motivo</label><select id="attempt-reason"><option value="absent">Destinatário ausente</option><option value="address">Endereço incompleto ou incorreto</option><option value="access">Acesso indisponível</option><option value="carrier">Problema da transportadora</option><option value="other">Outro motivo confirmado</option></select></div><div class="full"><label for="attempt-location">Local da tentativa</label><input id="attempt-location" required maxlength="120"></div><div class="full"><label for="attempt-note">Informação para o cliente</label><textarea id="attempt-note" required maxlength="1500"></textarea></div><label class="confirm-contact full"><input type="checkbox" id="attempt-confirmed" required>Confirmei esta tentativa real com a transportadora.</label>'+(number===3?'<label class="confirm-contact full"><input type="checkbox" id="attempt-fee">Habilitar reentrega opcional de R$ 10,00: condição informada ao cliente e falhas atribuíveis ao destinatário. Não habilitar para problema da loja/transportadora.</label>':'')+'<div class="full"><button>Confirmar tentativa '+number+'</button></div></form>';
      const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());$('attempt-date').value=now.toISOString().slice(0,19);
      $('attempt-form').onsubmit=action($('attempt-form').querySelector('button'),$('route-message'),async()=>{
        await api('/orders/'+encodeURIComponent(order.id)+'/attempt',{actionId,number,reason:$('attempt-reason').value,note:$('attempt-note').value,location:$('attempt-location').value,occurredAt:new Date($('attempt-date').value).toISOString(),carrierConfirmed:$('attempt-confirmed').checked,feeAuthorized:!!$('attempt-fee')?.checked});await detail(order.id);await load();$('route-message').textContent='Tentativa registrada. O cliente já pode ver a atualização.';
      });
      $('attempt-editor').scrollIntoView({behavior:'smooth',block:'nearest'});
    });
  }

  async function detail(id){currentId=id;const data=await api('/orders/'+encodeURIComponent(id)),order=data.order,a=order.address||{},paid=order.payment_status==='PAID',canUpdate=paid&&order.stage<5&&(!order.delivery||order.delivery.status==='active');$('route-message').textContent='';$('order-detail').innerHTML=`<span class="eyebrow">Detalhes do pedido</span><h2>${escape(order.order_code)}</h2><span class="badge ${paid?'paid':''}">${escape(status(order.payment_status))}</span><div class="grid"><div><h3>Cliente</h3><p>${escape(order.customer.name)}<br>${escape(order.customer.email)}<br>${escape(order.customer.phone)}</p></div><div><h3>Endereço</h3><p>${escape([a.street,a.streetNumber,a.complement,a.neighborhood,a.city,a.state,a.zipCode].filter(Boolean).join(', '))}</p></div></div>${order.items.map(item=>`<p class="muted">${escape(item.quantity)} × ${escape(item.title)}</p>`).join('')}<p><strong>Total: ${escape(money(order.amount))}</strong></p><p class="code">${escape(order.tracking_code)}</p><a class="button secondary" target="_blank" rel="noreferrer" href="/rastreio?codigo=${encodeURIComponent(order.tracking_code)}">Abrir acompanhamento</a>${attributionHtml(order.attribution)}${deliveryControls(order)}<h3>Atualizar entrega</h3><p class="notice">Registre uma movimentação após confirmar com a transportadora. O prazo de 15 dias é uma previsão; as etapas não avançam sozinhas.</p>${canUpdate?`<form id="route-form" class="grid"><div><label for="stage">Etapa atual</label><select id="stage" name="stage">${stages.slice(1).map((name,i)=>`<option value="${i+1}" ${order.stage===i+1?'selected':''}>${i+1}. ${name} · dias ${i*3+1}–${(i+1)*3}</option>`).join('')}</select></div><div><label for="occurredAt">Data e hora da movimentação</label><input type="datetime-local" step="1" id="occurredAt" name="occurredAt" required></div><div><label for="carrier">Transportadora</label><input id="carrier" name="carrier" maxlength="120" value="${escape(order.carrier)}"></div><div><label for="carrierCode">Código da transportadora (opcional)</label><input id="carrierCode" name="carrierCode" maxlength="120" value="${escape(order.carrier_code)}"></div><div><label for="location">Cidade / local da movimentação</label><input id="location" name="location" maxlength="120"></div><div><label for="estimatedDelivery">Previsão de entrega</label><input id="estimatedDelivery" name="estimatedDelivery" type="date" value="${escape(order.estimated_delivery||'')}"></div><div class="full"><label for="note">Informação que o cliente verá</label><textarea id="note" name="note" rows="3" required maxlength="1500" placeholder="Descreva a movimentação confirmada pela transportadora."></textarea></div><div class="full"><button>Salvar atualização de entrega</button></div></form>`:'<p class="muted">As alterações ficam disponíveis para pedidos pagos, em andamento e sem solicitação pendente.</p>'}<h3>E-mails automáticos</h3><p class="muted">Cada etapa e tentativa confirmada gera uma notificação, sem repetir a mesma etapa no ciclo. Falhas são tentadas novamente ao atualizar o painel, até cinco tentativas em 24 horas.</p><ul class="history">${(data.emails||[]).map(mail=>`<li>${escape(mail.order_id.startsWith("attempt/")?"Tentativa de entrega":mail.order_id.startsWith("delivery/")?"Etapa de entrega":mail.order_id.startsWith("paid/")?"Pagamento confirmado":"Pedido recebido")} · ${escape(mail.state==="sent"?"Aceito pelo serviço de e-mail":mail.expires_at<Date.now()?"Expirado — contatar atendimento":mail.attempts>=5?"Limite de tentativas — revisão manual": "Aguardando envio")} · ${mail.attempts} tentativa(s)</li>`).join("")}</ul><h3>Histórico de movimentações</h3><ul class="history">${data.events.length?data.events.map(item=>`<li><time>${escape(date(item.occurred_at))}</time><p><strong>${escape(stages[item.stage])}</strong></p><p>${escape(item.note)}</p><p class="muted">${escape(item.location)}</p></li>`).join(''):'<li class="muted">Ainda não há movimentações.</li>'}</ul>`;
    bindDeliveryControls(order);
    window.DeliveryMap.prepareAdmin({...order,paid_at:order.delivery?.cycleStartedAt||order.paid_at},data.events.filter(event=>!order.delivery||event.occurred_at>=order.delivery.cycleStartedAt));
    if(canUpdate){const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());$('occurredAt').value=now.toISOString().slice(0,19);$('route-form').addEventListener('submit',action($('route-form').querySelector('button'),$('route-message'),async()=>{const form={...Object.fromEntries(new FormData($('route-form'))),...$('route-form').mapPoint()};form.occurredAt=new Date(form.occurredAt).toISOString();const result=await api('/orders/'+encodeURIComponent(currentId)+'/route',form);await detail(currentId);$('route-message').textContent='Movimentação salva. E-mail: '+(result.emailStatus==='sent'?'enviado.':result.emailStatus==='not_configured'?'não configurado.':'aguardando nova tentativa.');await load();}));}
    if(!$('order-dialog').open)$('order-dialog').showModal();
  }
  $('orders').onclick=async event=>{const button=event.target.closest('[data-order]');if(!button)return;button.disabled=true;try{await detail(button.dataset.order);}catch(error){$('dashboard-message').textContent=error.message;}finally{button.disabled=false;}};
  api('/session').then(enter).catch(()=>showLogin());
})();
